#include <string>

using namespace std;

class Solution {
public:
    string toHex(int num) {
        if (num == 0) return "0";
        unsigned int n = num;
        string hex = "";
        string digits = "0123456789abcdef";
        while (n) {
            hex = digits[n % 16] + hex;
            n /= 16;
        }
        return hex;
    }
};
